window.TASK_BANKS[63] = {"version":1,"topicId":63,"tasks":[{"id":"63.1","codeLang":"python","answer":"учебная запись\nкопия","answerLang":"text","explanation":"src.backup(dst) переносит данные из src в dst. Это независимая БД, не второе имя исходного файла. Изменение копии не меняет источник. Направление обратного вызова могло бы уничтожить исходные данные.","verified":"3.14","wrong":["копия\nкопия","копия\nучебная запись"]},{"id":"63.2","codeLang":"python","answer":"0\n1","answerLang":"text","explanation":"Commit в WAL-режиме не обязан сразу переписывать основной db-файл. Простое копирование одного файла здесь теряет строку, хотя commit был. Штатный backup читает согласованную БД через SQLite. Нельзя по очереди копировать db/wal/shm и обещать согласованный снимок живой базы.","verified":"3.14","wrong":["1\n1","0\n0"]},{"id":"63.3","codeLang":"python","answer":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\ndef read_titles(path):\n    path=Path(path).resolve(strict=True)\n    with closing(sqlite3.connect(path.as_uri()+'?mode=ro',uri=True)) as con:\n        return [row[0] for row in con.execute('SELECT title FROM notes ORDER BY id')]","answerLang":"python","explanation":"Обычный connect(path) создаёт отсутствующий файл, а пустая БД может выглядеть как успешное восстановление без записей. resolve(strict=True) проверяет существование, as_uri корректно кодирует # и другие символы, mode=ro запрещает запись. Closing закрывает только принадлежащее функции соединение.","verified":"3.14","check":{"append":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef _seed(path,revision=0,rows=()):\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE meta(revision INTEGER)')\n        con.execute('CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT,done INTEGER,version INTEGER)')\n        con.execute('INSERT INTO meta VALUES (?)',(revision,))\n        con.executemany('INSERT INTO notes VALUES (?,?,?,?)',rows)\n        con.commit()\ndef _rows(path):\n    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)) as con:\n        return con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\ndef _raises(types,fn,*args):\n    try:fn(*args)\n    except types:return\n    raise AssertionError('Нужен отказ, не видимость успеха')\nwith TemporaryDirectory() as folder:\n    root=Path(folder);path=root/'Учебная БД # 1.db'\n    _seed(path,rows=[(7,\"O'Neil\",0,1),(0,'',1,2)])\n    before=path.read_bytes()\n    assert read_titles(path)==['',\"O'Neil\"]\n    assert path.read_bytes()==before\n    _raises((FileNotFoundError,sqlite3.OperationalError),read_titles,root/'missing.db')\n    assert not (root/'missing.db').exists()\n    path.rename(root/'closed.db')\nprint('OK')","expect":"OK"}},{"id":"63.4","codeLang":"python","answer":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\ndef publish_new(stage,destination):\n    os.link(stage,destination)","answerLang":"python","explanation":"Жёсткая ссылка добавляет имя уже существующему файлу. Ядро откажет, если destination занят: отдельная проверка exists не даёт такой гарантии. После удаления временного имени опубликованное имя сохраняется. Рабочую БД нельзя напрямую связывать с резервной: оба имени тогда меняли бы одни данные.","verified":"3.14","check":{"append":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef _seed(path,revision=0,rows=()):\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE meta(revision INTEGER)')\n        con.execute('CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT,done INTEGER,version INTEGER)')\n        con.execute('INSERT INTO meta VALUES (?)',(revision,))\n        con.executemany('INSERT INTO notes VALUES (?,?,?,?)',rows)\n        con.commit()\ndef _rows(path):\n    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)) as con:\n        return con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\ndef _raises(types,fn,*args):\n    try:fn(*args)\n    except types:return\n    raise AssertionError('Нужен отказ, не видимость успеха')\nwith TemporaryDirectory() as folder:\n    root=Path(folder);stage=root/'prepared';dest=root/'published'\n    stage.write_bytes(b'complete snapshot')\n    assert publish_new(stage,dest) is None\n    assert stage.read_bytes()==dest.read_bytes()==b'complete snapshot'\n    _raises(FileExistsError,publish_new,stage,dest)\n    _raises(FileExistsError,publish_new,stage,stage)\n    assert dest.read_bytes()==b'complete snapshot'\n    stage.unlink();assert dest.read_bytes()==b'complete snapshot'\nprint('OK')","expect":"OK"}},{"id":"63.5","codeLang":"python","answer":"['commit']\nTrue","answerLang":"text","explanation":"Отдельный читатель видит зафиксированное состояние. Резервирование не обязано и не должно коммитить чужую транзакцию. Новое соединение также отделяет жизненный цикл снимка от соединения живого приложения.","verified":"3.14","wrong":["['commit', 'pending']\nFalse","['commit']\nFalse"]},{"id":"63.6","codeLang":"python","answer":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef copy_database(source,destination):\n    source=Path(source).resolve(strict=True)\n    destination=Path(destination).absolute()\n    if not source.is_file():raise ValueError('Нужен файл')\n    if destination.exists() or destination.is_symlink():raise FileExistsError(destination)\n    with TemporaryDirectory(dir=destination.parent) as folder:\n        stage=Path(folder)/'snapshot.db'\n        with closing(sqlite3.connect(source.as_uri()+'?mode=ro',uri=True,timeout=0)) as src,closing(sqlite3.connect(stage)) as dst:\n            deadline=time.monotonic()+0.5\n            def progress(status,remaining,total):\n                if time.monotonic()>deadline:raise TimeoutError('БД занята')\n            src.backup(dst,pages=32,progress=progress,sleep=0.01)\n            dst.execute('PRAGMA journal_mode=DELETE')\n        os.link(stage,destination)","answerLang":"python","explanation":"Временная папка отделяет незавершённую копию от опубликованной. SQLite читает целое committed состояние, затем целевой журнал сводится в самостоятельный файл. Закрытие до os.link важно и для Windows. Таймаут connect не ограничивает весь цикл backup: callback должен прервать повторные попытки. Жёсткая ссылка создаёт новое имя подготовленной копии и не заменяет поздно появившуюся чужую работу.","verified":"3.14","check":{"append":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef _seed(path,revision=0,rows=()):\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE meta(revision INTEGER)')\n        con.execute('CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT,done INTEGER,version INTEGER)')\n        con.execute('INSERT INTO meta VALUES (?)',(revision,))\n        con.executemany('INSERT INTO notes VALUES (?,?,?,?)',rows)\n        con.commit()\ndef _rows(path):\n    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)) as con:\n        return con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\ndef _raises(types,fn,*args):\n    try:fn(*args)\n    except types:return\n    raise AssertionError('Нужен отказ, не видимость успеха')\n\ndef _copy_checks(fn):\n    with TemporaryDirectory() as folder:\n        root=Path(folder);src=root/'source # БД.db';dest=root/'new.db'\n        expected=[(0,'',0,1),(4,\"O'Neil\",1,9)]\n        _seed(src,3,expected);before=src.read_bytes()\n        assert fn(src,dest) is None\n        assert _rows(dest)==expected and src.read_bytes()==before\n        with closing(sqlite3.connect(dest)) as con:\n            con.execute(\"UPDATE notes SET title='changed copy'\");con.commit()\n        assert _rows(src)==expected\n        existing=root/'keep.db';existing.write_bytes(b'MANUAL_WORK')\n        _raises(FileExistsError,fn,src,existing);assert existing.read_bytes()==b'MANUAL_WORK'\n        _raises(FileExistsError,fn,src,src);assert src.read_bytes()==before\n        _raises((FileNotFoundError,sqlite3.OperationalError),fn,root/'missing.db',root/'must-not-exist.db')\n        assert not (root/'missing.db').exists() and not (root/'must-not-exist.db').exists()\n        with closing(sqlite3.connect(src)) as writer:\n            writer.execute('PRAGMA journal_mode=WAL');writer.execute('PRAGMA wal_autocheckpoint=0')\n            writer.execute(\"INSERT INTO notes VALUES (8,'WAL committed',0,1)\");writer.commit()\n            writer.execute(\"INSERT INTO notes VALUES (9,'pending',0,1)\")\n            assert fn(src,root/'wal-copy.db') is None\n            assert _rows(root/'wal-copy.db')==expected+[(8,'WAL committed',0,1)]\n            with closing(sqlite3.connect(root/'wal-copy.db')) as copied:\n                assert copied.execute('PRAGMA journal_mode').fetchone()[0]=='delete'\n            assert writer.in_transaction\n            writer.rollback()\n        original=sqlite3.connect\n        raced=root/'raced.db'\n        class DuringBackup(sqlite3.Connection):\n            def backup(self,target,*args,**kwargs):\n                raced.write_bytes(b'NEWER_WORK')\n                return super().backup(target,*args,**kwargs)\n        def connect(*args,**kwargs):\n            kwargs.setdefault('factory',DuringBackup);return original(*args,**kwargs)\n        sqlite3.connect=connect\n        try:_raises(FileExistsError,fn,src,raced)\n        finally:sqlite3.connect=original\n        assert raced.read_bytes()==b'NEWER_WORK'\n        failure=root/'failed.db';listing={p.name for p in root.iterdir()}\n        class FailedBackup(sqlite3.Connection):\n            def backup(self,target,*args,**kwargs):\n                target.execute('CREATE TABLE partial(value INTEGER)')\n                raise RuntimeError('synthetic backup failure')\n        def connect(*args,**kwargs):\n            kwargs.setdefault('factory',FailedBackup);return original(*args,**kwargs)\n        sqlite3.connect=connect\n        try:_raises(RuntimeError,fn,src,failure)\n        finally:sqlite3.connect=original\n        assert not failure.exists() and {p.name for p in root.iterdir()}==listing\n    with TemporaryDirectory() as folder:\n        src=Path(folder)/'locked.db';dest=Path(folder)/'copy.db';_seed(src)\n        with closing(sqlite3.connect(src)) as locked:\n            locked.execute('BEGIN EXCLUSIVE')\n            start=time.monotonic()\n            _raises((TimeoutError,sqlite3.OperationalError),fn,src,dest)\n            assert time.monotonic()-start<1.5 and not dest.exists()\n            locked.rollback()\nassert _copy_checks(copy_database) is None\nprint('OK')","expect":"OK"}},{"id":"63.7","codeLang":"python","answer":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef inspect_snapshot(path):\n    path=Path(path).resolve(strict=True)\n    if not path.is_file():raise ValueError('Нужен файл')\n    with closing(sqlite3.connect(path.as_uri()+'?mode=ro',uri=True,timeout=0)) as con:\n        if con.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]:\n            raise ValueError('Повреждённая БД')\n        tables={r[0] for r in con.execute(\"SELECT name FROM sqlite_schema WHERE type='table'\")}\n        if not {'notes','meta'}<=tables:raise ValueError('Не учебный снимок')\n        if {r[1] for r in con.execute('PRAGMA table_info(notes)')}!={'id','title','done','version'}:\n            raise ValueError('Неизвестная схема notes')\n        if {r[1] for r in con.execute('PRAGMA table_info(meta)')}!={'revision'}:\n            raise ValueError('Неизвестная схема meta')\n        revisions=con.execute('SELECT revision FROM meta').fetchall()\n        if len(revisions)!=1 or type(revisions[0][0]) is not int or revisions[0][0]<0:\n            raise ValueError('Неверная ревизия')\n        rows=con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\n        for id,title,done,version in rows:\n            if type(id) is not int or type(title) is not str or type(done) is not int or done not in (0,1) or type(version) is not int or version<=0:\n                raise ValueError('Неверные данные notes')\n        return {'revision':revisions[0][0],'total':len(rows),'done':sum(r[2] for r in rows)}","answerLang":"python","explanation":"Файл может открываться и всё же содержать не ту схему или логически недопустимые записи. integrity_check проверяет структуру SQLite, но не прикладное правило done∈{0,1}. Ревизия — отдельные явные данные приложения, не версия одной заметки и не число строк. Отсутствие заметок не делает проверенный снимок бесполезным.","verified":"3.14","check":{"append":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef _seed(path,revision=0,rows=()):\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE meta(revision INTEGER)')\n        con.execute('CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT,done INTEGER,version INTEGER)')\n        con.execute('INSERT INTO meta VALUES (?)',(revision,))\n        con.executemany('INSERT INTO notes VALUES (?,?,?,?)',rows)\n        con.commit()\ndef _rows(path):\n    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)) as con:\n        return con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\ndef _raises(types,fn,*args):\n    try:fn(*args)\n    except types:return\n    raise AssertionError('Нужен отказ, не видимость успеха')\n\nwith TemporaryDirectory() as folder:\n    root=Path(folder);path=root/'good.db';_seed(path,0,[(0,'',0,1),(8,\"O'Neil\",1,3)])\n    before=path.read_bytes()\n    assert inspect_snapshot(path)=={'revision':0,'total':2,'done':1}\n    assert path.read_bytes()==before\n    empty=root/'empty.db';_seed(empty,11)\n    assert inspect_snapshot(empty)=={'revision':11,'total':0,'done':0}\n    for index,sql in enumerate([\"UPDATE meta SET revision=-1\",\"INSERT INTO meta VALUES (4)\",\"UPDATE notes SET done=2\",\"UPDATE notes SET version=0\",\"UPDATE notes SET title=NULL\",\"ALTER TABLE notes ADD COLUMN extra TEXT\"]):\n        bad=root/('bad'+str(index)+'.db');_seed(bad,1,[(1,'note',0,1)])\n        with closing(sqlite3.connect(bad)) as con:con.execute(sql);con.commit()\n        _raises(ValueError,inspect_snapshot,bad)\n    corrupt=root/'corrupt';corrupt.write_bytes(b'not sqlite')\n    _raises(sqlite3.DatabaseError,inspect_snapshot,corrupt)\n    _raises((FileNotFoundError,sqlite3.OperationalError),inspect_snapshot,root/'missing.db')\n    assert not (root/'missing.db').exists()\n    alternate=root/'alternate.db'\n    with closing(sqlite3.connect(alternate)) as con:\n        con.executescript(\"CREATE TABLE notes(version INTEGER,done INTEGER,title TEXT,id INTEGER PRIMARY KEY);CREATE TABLE meta(revision INTEGER);INSERT INTO meta VALUES (4);INSERT INTO notes VALUES (2,0,'yes',0);CREATE TABLE audit(message TEXT)\")\n    assert inspect_snapshot(alternate)=={'revision':4,'total':1,'done':0}\nprint('OK')","expect":"OK"}},{"id":"63.8","codeLang":"python","answer":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef inspect_snapshot(path):\n    path=Path(path).resolve(strict=True)\n    if not path.is_file():raise ValueError('Нужен файл')\n    with closing(sqlite3.connect(path.as_uri()+'?mode=ro',uri=True,timeout=0)) as con:\n        if con.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]:\n            raise ValueError('Повреждённая БД')\n        tables={r[0] for r in con.execute(\"SELECT name FROM sqlite_schema WHERE type='table'\")}\n        if not {'notes','meta'}<=tables:raise ValueError('Не учебный снимок')\n        if {r[1] for r in con.execute('PRAGMA table_info(notes)')}!={'id','title','done','version'}:\n            raise ValueError('Неизвестная схема notes')\n        if {r[1] for r in con.execute('PRAGMA table_info(meta)')}!={'revision'}:\n            raise ValueError('Неизвестная схема meta')\n        revisions=con.execute('SELECT revision FROM meta').fetchall()\n        if len(revisions)!=1 or type(revisions[0][0]) is not int or revisions[0][0]<0:\n            raise ValueError('Неверная ревизия')\n        rows=con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\n        for id,title,done,version in rows:\n            if type(id) is not int or type(title) is not str or type(done) is not int or done not in (0,1) or type(version) is not int or version<=0:\n                raise ValueError('Неверные данные notes')\n        return {'revision':revisions[0][0],'total':len(rows),'done':sum(r[2] for r in rows)}\n\ndef candidate_revision(path):\n    try:return inspect_snapshot(path)['revision']\n    except (FileNotFoundError,ValueError):return None\n    except sqlite3.DatabaseError as error:\n        if (getattr(error,'sqlite_errorcode',0)&255) in (sqlite3.SQLITE_CORRUPT,sqlite3.SQLITE_NOTADB):return None\n        raise","answerLang":"python","explanation":"Нулевая ревизия — значение, не отсутствие результата. Повреждение формата и временная занятость требуют разных действий. sqlite_errorcode может содержать расширенный код: младший байт выделяет базовую категорию. Общий except скрывал бы и lock, и ошибку своей программы.","verified":"3.14","check":{"append":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef _seed(path,revision=0,rows=()):\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE meta(revision INTEGER)')\n        con.execute('CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT,done INTEGER,version INTEGER)')\n        con.execute('INSERT INTO meta VALUES (?)',(revision,))\n        con.executemany('INSERT INTO notes VALUES (?,?,?,?)',rows)\n        con.commit()\ndef _rows(path):\n    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)) as con:\n        return con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\ndef _raises(types,fn,*args):\n    try:fn(*args)\n    except types:return\n    raise AssertionError('Нужен отказ, не видимость успеха')\n\nwith TemporaryDirectory() as folder:\n    root=Path(folder);zero=root/'zero.db';_seed(zero,0)\n    assert candidate_revision(zero)==0\n    assert candidate_revision(root/'missing.db') is None\n    assert not (root/'missing.db').exists()\n    corrupt=root/'corrupt';corrupt.write_bytes(b'not sqlite')\n    assert candidate_revision(corrupt) is None\n    bad=root/'bad.db';_seed(bad,-1)\n    assert candidate_revision(bad) is None\n    with closing(sqlite3.connect(zero)) as locked:\n        locked.execute('BEGIN EXCLUSIVE')\n        _raises(sqlite3.OperationalError,candidate_revision,zero)\n        locked.rollback()\nprint('OK')","expect":"OK"}},{"id":"63.9","codeLang":"python","answer":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef inspect_snapshot(path):\n    path=Path(path).resolve(strict=True)\n    if not path.is_file():raise ValueError('Нужен файл')\n    with closing(sqlite3.connect(path.as_uri()+'?mode=ro',uri=True,timeout=0)) as con:\n        if con.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]:\n            raise ValueError('Повреждённая БД')\n        tables={r[0] for r in con.execute(\"SELECT name FROM sqlite_schema WHERE type='table'\")}\n        if not {'notes','meta'}<=tables:raise ValueError('Не учебный снимок')\n        if {r[1] for r in con.execute('PRAGMA table_info(notes)')}!={'id','title','done','version'}:\n            raise ValueError('Неизвестная схема notes')\n        if {r[1] for r in con.execute('PRAGMA table_info(meta)')}!={'revision'}:\n            raise ValueError('Неизвестная схема meta')\n        revisions=con.execute('SELECT revision FROM meta').fetchall()\n        if len(revisions)!=1 or type(revisions[0][0]) is not int or revisions[0][0]<0:\n            raise ValueError('Неверная ревизия')\n        rows=con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\n        for id,title,done,version in rows:\n            if type(id) is not int or type(title) is not str or type(done) is not int or done not in (0,1) or type(version) is not int or version<=0:\n                raise ValueError('Неверные данные notes')\n        return {'revision':revisions[0][0],'total':len(rows),'done':sum(r[2] for r in rows)}\n\ndef backup_notes(source,destination):\n    source=Path(source).resolve(strict=True)\n    destination=Path(destination).absolute()\n    if not source.is_file():raise ValueError('Нужен файл')\n    if destination.exists() or destination.is_symlink():raise FileExistsError(destination)\n    with TemporaryDirectory(dir=destination.parent) as folder:\n        stage=Path(folder)/'snapshot.db'\n        with closing(sqlite3.connect(source.as_uri()+'?mode=ro',uri=True,timeout=0)) as src,closing(sqlite3.connect(stage)) as dst:\n            deadline=time.monotonic()+0.5\n            def progress(status,remaining,total):\n                if time.monotonic()>deadline:raise TimeoutError('БД занята')\n            src.backup(dst,pages=32,progress=progress,sleep=0.01)\n            dst.execute('PRAGMA journal_mode=DELETE')\n        report=inspect_snapshot(stage)\n        os.link(stage,destination)\n        return report","answerLang":"python","explanation":"Доверять нужно проверенному результату копирования. Между проверкой живой БД и backup другой писатель мог зафиксировать изменение. Отчёт строится по закрытому снимку, а публикация нового имени выполняется после проверки. Старый файл и поздно появившийся destination не жертвуются ради видимости успеха.","verified":"3.14","hint":"Составьте порядок: RO-источник → свой временный файл → проверка фактической копии → закрытие → публикация нового имени. Отчёт относится к снимку.","check":{"append":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef _seed(path,revision=0,rows=()):\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE meta(revision INTEGER)')\n        con.execute('CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT,done INTEGER,version INTEGER)')\n        con.execute('INSERT INTO meta VALUES (?)',(revision,))\n        con.executemany('INSERT INTO notes VALUES (?,?,?,?)',rows)\n        con.commit()\ndef _rows(path):\n    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)) as con:\n        return con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\ndef _raises(types,fn,*args):\n    try:fn(*args)\n    except types:return\n    raise AssertionError('Нужен отказ, не видимость успеха')\n\ndef _copy_checks(fn):\n    with TemporaryDirectory() as folder:\n        root=Path(folder);src=root/'source # БД.db';dest=root/'new.db'\n        expected=[(0,'',0,1),(4,\"O'Neil\",1,9)]\n        _seed(src,3,expected);before=src.read_bytes()\n        assert fn(src,dest) is None\n        assert _rows(dest)==expected and src.read_bytes()==before\n        with closing(sqlite3.connect(dest)) as con:\n            con.execute(\"UPDATE notes SET title='changed copy'\");con.commit()\n        assert _rows(src)==expected\n        existing=root/'keep.db';existing.write_bytes(b'MANUAL_WORK')\n        _raises(FileExistsError,fn,src,existing);assert existing.read_bytes()==b'MANUAL_WORK'\n        _raises(FileExistsError,fn,src,src);assert src.read_bytes()==before\n        _raises((FileNotFoundError,sqlite3.OperationalError),fn,root/'missing.db',root/'must-not-exist.db')\n        assert not (root/'missing.db').exists() and not (root/'must-not-exist.db').exists()\n        with closing(sqlite3.connect(src)) as writer:\n            writer.execute('PRAGMA journal_mode=WAL');writer.execute('PRAGMA wal_autocheckpoint=0')\n            writer.execute(\"INSERT INTO notes VALUES (8,'WAL committed',0,1)\");writer.commit()\n            writer.execute(\"INSERT INTO notes VALUES (9,'pending',0,1)\")\n            assert fn(src,root/'wal-copy.db') is None\n            assert _rows(root/'wal-copy.db')==expected+[(8,'WAL committed',0,1)]\n            with closing(sqlite3.connect(root/'wal-copy.db')) as copied:\n                assert copied.execute('PRAGMA journal_mode').fetchone()[0]=='delete'\n            assert writer.in_transaction\n            writer.rollback()\n        original=sqlite3.connect\n        raced=root/'raced.db'\n        class DuringBackup(sqlite3.Connection):\n            def backup(self,target,*args,**kwargs):\n                raced.write_bytes(b'NEWER_WORK')\n                return super().backup(target,*args,**kwargs)\n        def connect(*args,**kwargs):\n            kwargs.setdefault('factory',DuringBackup);return original(*args,**kwargs)\n        sqlite3.connect=connect\n        try:_raises(FileExistsError,fn,src,raced)\n        finally:sqlite3.connect=original\n        assert raced.read_bytes()==b'NEWER_WORK'\n        failure=root/'failed.db';listing={p.name for p in root.iterdir()}\n        class FailedBackup(sqlite3.Connection):\n            def backup(self,target,*args,**kwargs):\n                target.execute('CREATE TABLE partial(value INTEGER)')\n                raise RuntimeError('synthetic backup failure')\n        def connect(*args,**kwargs):\n            kwargs.setdefault('factory',FailedBackup);return original(*args,**kwargs)\n        sqlite3.connect=connect\n        try:_raises(RuntimeError,fn,src,failure)\n        finally:sqlite3.connect=original\n        assert not failure.exists() and {p.name for p in root.iterdir()}==listing\n    with TemporaryDirectory() as folder:\n        src=Path(folder)/'locked.db';dest=Path(folder)/'copy.db';_seed(src)\n        with closing(sqlite3.connect(src)) as locked:\n            locked.execute('BEGIN EXCLUSIVE')\n            start=time.monotonic()\n            _raises((TimeoutError,sqlite3.OperationalError),fn,src,dest)\n            assert time.monotonic()-start<1.5 and not dest.exists()\n            locked.rollback()\n\ndef _backup_checks(fn):\n    def just_copy(source,destination):\n        value=fn(source,destination)\n        assert set(value)=={'revision','total','done'}\n        with closing(sqlite3.connect(destination)) as con:\n            rows=con.execute('SELECT revision FROM meta').fetchall()\n            notes=con.execute('SELECT done FROM notes').fetchall()\n        assert value=={'revision':rows[0][0],'total':len(notes),'done':sum(r[0] for r in notes)}\n    _copy_checks(just_copy)\n    with TemporaryDirectory() as folder:\n        root=Path(folder);src=root/'invalid.db';dest=root/'not-published.db'\n        _seed(src,2,[(0,'bad flag',2,1)])\n        _raises(ValueError,fn,src,dest);assert not dest.exists()\n        _seed(root/'empty.db',0)\n        assert fn(root/'empty.db',root/'empty-copy.db')=={'revision':0,'total':0,'done':0}\n        good=root/'changing.db';_seed(good,3,[(0,'before',0,1)])\n        original=sqlite3.connect\n        class ConcurrentCommit(sqlite3.Connection):\n            def backup(self,target,*args,**kwargs):\n                with closing(original(good)) as writer:\n                    writer.execute('UPDATE meta SET revision=4')\n                    writer.execute(\"INSERT INTO notes VALUES (9,'concurrent commit',1,1)\");writer.commit()\n                return super().backup(target,*args,**kwargs)\n        def connect(*args,**kwargs):\n            kwargs.setdefault('factory',ConcurrentCommit);return original(*args,**kwargs)\n        sqlite3.connect=connect\n        try:report=fn(good,root/'changing-copy.db')\n        finally:sqlite3.connect=original\n        assert report=={'revision':4,'total':2,'done':1}\nassert _backup_checks(backup_notes) is None\nprint('OK')","expect":"OK"}},{"id":"63.10","codeLang":"python","answer":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef inspect_snapshot(path):\n    path=Path(path).resolve(strict=True)\n    if not path.is_file():raise ValueError('Нужен файл')\n    with closing(sqlite3.connect(path.as_uri()+'?mode=ro',uri=True,timeout=0)) as con:\n        if con.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]:\n            raise ValueError('Повреждённая БД')\n        tables={r[0] for r in con.execute(\"SELECT name FROM sqlite_schema WHERE type='table'\")}\n        if not {'notes','meta'}<=tables:raise ValueError('Не учебный снимок')\n        if {r[1] for r in con.execute('PRAGMA table_info(notes)')}!={'id','title','done','version'}:\n            raise ValueError('Неизвестная схема notes')\n        if {r[1] for r in con.execute('PRAGMA table_info(meta)')}!={'revision'}:\n            raise ValueError('Неизвестная схема meta')\n        revisions=con.execute('SELECT revision FROM meta').fetchall()\n        if len(revisions)!=1 or type(revisions[0][0]) is not int or revisions[0][0]<0:\n            raise ValueError('Неверная ревизия')\n        rows=con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\n        for id,title,done,version in rows:\n            if type(id) is not int or type(title) is not str or type(done) is not int or done not in (0,1) or type(version) is not int or version<=0:\n                raise ValueError('Неверные данные notes')\n        return {'revision':revisions[0][0],'total':len(rows),'done':sum(r[2] for r in rows)}\n\ndef backup_notes(source,destination):\n    source=Path(source).resolve(strict=True)\n    destination=Path(destination).absolute()\n    if not source.is_file():raise ValueError('Нужен файл')\n    if destination.exists() or destination.is_symlink():raise FileExistsError(destination)\n    with TemporaryDirectory(dir=destination.parent) as folder:\n        stage=Path(folder)/'snapshot.db'\n        with closing(sqlite3.connect(source.as_uri()+'?mode=ro',uri=True,timeout=0)) as src,closing(sqlite3.connect(stage)) as dst:\n            deadline=time.monotonic()+0.5\n            def progress(status,remaining,total):\n                if time.monotonic()>deadline:raise TimeoutError('БД занята')\n            src.backup(dst,pages=32,progress=progress,sleep=0.01)\n            dst.execute('PRAGMA journal_mode=DELETE')\n        report=inspect_snapshot(stage)\n        os.link(stage,destination)\n        return report\n\ndef recover_latest(candidates,destination):\n    best=None\n    for path in candidates:\n        try:report=inspect_snapshot(path)\n        except (FileNotFoundError,ValueError):continue\n        except sqlite3.DatabaseError as error:\n            if (getattr(error,'sqlite_errorcode',0)&255) in (sqlite3.SQLITE_CORRUPT,sqlite3.SQLITE_NOTADB):continue\n            raise\n        if best is None or report['revision']>best[0]:best=(report['revision'],path)\n    if best is None:raise ValueError('Нет проверенной копии')\n    return backup_notes(best[1],destination)","answerLang":"python","explanation":"Выбор копии и создание новой рабочей БД — отдельные действия. Ревизия определяется приложением заранее; свежая пустая база может означать законное удаление всех заметок. Занятость последней копии не даёт права молча выбрать старую. Изменение восстановленного файла не должно изменить архив; поэтому нельзя делать жёсткую ссылку прямо на выбранный источник.","verified":"3.14","hint":"Сначала различите пригодность/отказ и выберите по явной ревизии. Затем получите независимую проверенную копию в новом пути, сохраняя архивы и текущую работу.","check":{"append":"import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef _seed(path,revision=0,rows=()):\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE meta(revision INTEGER)')\n        con.execute('CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT,done INTEGER,version INTEGER)')\n        con.execute('INSERT INTO meta VALUES (?)',(revision,))\n        con.executemany('INSERT INTO notes VALUES (?,?,?,?)',rows)\n        con.commit()\ndef _rows(path):\n    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)) as con:\n        return con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\ndef _raises(types,fn,*args):\n    try:fn(*args)\n    except types:return\n    raise AssertionError('Нужен отказ, не видимость успеха')\n\nwith TemporaryDirectory() as folder:\n    root=Path(folder);low=root/'low.db';latest=root/'latest.db';tie=root/'same-revision.db'\n    _seed(low,4,[(0,'older',1,99)]);_seed(latest,8);_seed(tie,8,[(7,'tie must lose',0,1)])\n    os.utime(low,(2000000000,2000000000));os.utime(latest,(1000000000,1000000000))\n    bad=root/'bad.db';_seed(bad,99,[(0,'invalid',2,1)])\n    corrupt=root/'corrupt';corrupt.write_bytes(b'not sqlite')\n    missing=root/'missing.db';dest=root/'restored.db'\n    before={p:p.read_bytes() for p in (low,latest,tie,bad,corrupt)}\n    assert recover_latest([missing,corrupt,bad,low,latest,tie],dest)=={'revision':8,'total':0,'done':0}\n    assert _rows(dest)==[] and not missing.exists()\n    assert all(p.read_bytes()==value for p,value in before.items())\n    with closing(sqlite3.connect(dest)) as con:\n        con.execute(\"INSERT INTO notes VALUES (1,'restored edit',0,1)\");con.commit()\n    assert _rows(latest)==[]\n    _raises(FileExistsError,recover_latest,[low],dest);assert _rows(dest)==[(1,'restored edit',0,1)]\n    _raises(ValueError,recover_latest,[],root/'none.db');assert not (root/'none.db').exists()\n    _raises(ValueError,recover_latest,[missing,bad,corrupt],root/'none.db');assert not (root/'none.db').exists()\n    _raises(FileExistsError,recover_latest,[low],low);assert low.read_bytes()==before[low]\n    zero=root/'zero.db';_seed(zero,0)\n    assert recover_latest([zero],root/'zero-restored.db')=={'revision':0,'total':0,'done':0}\n    with closing(sqlite3.connect(latest)) as locked:\n        locked.execute('BEGIN EXCLUSIVE')\n        _raises(sqlite3.OperationalError,recover_latest,[low,latest],root/'must-not-fallback.db')\n        assert not (root/'must-not-fallback.db').exists();locked.rollback()\n    original=sqlite3.connect;raced=root/'race.db'\n    class DuringBackup(sqlite3.Connection):\n        def backup(self,target,*args,**kwargs):\n            raced.write_bytes(b'NEW_MANUAL_WORK')\n            return super().backup(target,*args,**kwargs)\n    def connect(*args,**kwargs):\n        kwargs.setdefault('factory',DuringBackup);return original(*args,**kwargs)\n    sqlite3.connect=connect\n    try:_raises(FileExistsError,recover_latest,[low],raced)\n    finally:sqlite3.connect=original\n    assert raced.read_bytes()==b'NEW_MANUAL_WORK'\nprint('OK')","expect":"OK"}}]};
